class AdminRevenuePage extends ConsumerStatefulWidget {
  const AdminRevenuePage({super.key});
  @override ConsumerState<AdminRevenuePage> createState() => _AdminRevenuePageState();
}

class _AdminRevenuePageState extends ConsumerState<AdminRevenuePage> {
  int preset = 2;
  int group = 0;
  DateTimeRange get range { final now = DateTime.now(); final today = DateTime(now.year, now.month, now.day); return switch (preset) { 0 => DateTimeRange(start: today, end: today), 1 => DateTimeRange(start: today.subtract(const Duration(days: 6)), end: today), 2 => DateTimeRange(start: today.subtract(const Duration(days: 29)), end: today), 3 => DateTimeRange(start: DateTime(now.year, now.month), end: today), 4 => DateTimeRange(start: DateTime(now.year, now.month - 1), end: DateTime(now.year, now.month, 0)), _ => DateTimeRange(start: DateTime(now.year), end: today) }; }
  @override Widget build(BuildContext context) { final request = AdminRevenueRequest(range.start, range.end, const ['day','week','month'][group]); final report = ref.watch(adminRevenueProvider(request)); return CustomScrollView(slivers: [SliverToBoxAdapter(child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [Row(children: [Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text('admin.revenue.title'.tr(), style: context.textStyles.headlineSmall), Text('admin.revenue.subtitle'.tr())])), if (report.value != null) HBButton.secondary(label: 'admin.revenue.export'.tr(), icon: Icons.download_outlined, onPressed: () => _export(report.value!))]), const SizedBox(height: AppSpacing.md), HBSegmentedTabs(labels: ['admin.revenue.period.today'.tr(), 'admin.revenue.period.7d'.tr(), 'admin.revenue.period.30d'.tr(), 'admin.revenue.period.month'.tr(), 'admin.revenue.period.last_month'.tr(), 'admin.revenue.period.year'.tr()], selectedIndex: preset, scrollable: true, onChanged: (value) => setState(() => preset = value)), const SizedBox(height: AppSpacing.sm), SizedBox(width: 360, child: HBSegmentedTabs(labels: ['admin.revenue.group.day'.tr(), 'admin.revenue.group.week'.tr(), 'admin.revenue.group.month'.tr()], selectedIndex: group, onChanged: (value) => setState(() => group = value))), const SizedBox(height: AppSpacing.md), report.when(loading: () => const LinearProgressIndicator(), error: (_, __) => HBEmptyState(icon: Icons.error_outline, title: 'admin.revenue.error'.tr(), message: 'errors.network'.tr()), data: (data) => AdminRevenueContent(report: data)), const SizedBox(height: AppSpacing.xl)]))]); }
  Future<void> _export(AdminRevenueReport report) async { final rows = <List<Object?>>[['section','period','currency','amount','count']]; for (final item in p42Maps(report.ads['series'])) { rows.add(['ads', item['period'], item['currency_code'], item['charged'], item['charges']]); } for (final item in p42Maps(report.marketplace['series'])) { rows.add(['marketplace', item['period'], item['currency_code'], item['gmv'], item['orders']]); } for (final item in p42Maps(report.ads['top_advertisers'])) { rows.add(['advertiser', item['name'], item['currency_code'], item['charged'], item['charges']]); } for (final item in p42Maps(report.ads['by_country'])) { rows.add(['country', item['country_code'], item['currency_code'], item['charged'], item['charges']]); } final csv = rows.map((row) => row.map((cell) => '"${(cell ?? '').toString().replaceAll('"', '""')}"').join(',')).join('\n'); final bytes = Uint8List.fromList(utf8.encode(csv)); if (kIsWeb) { downloadDiaryFile(bytes, 'hb-revenue.csv', 'text/csv'); } else { await Share.shareXFiles([XFile.fromData(bytes, mimeType: 'text/csv', name: 'hb-revenue.csv')]); } }
}

class AdminRevenueContent extends StatelessWidget {
  final AdminRevenueReport report;
  const AdminRevenueContent({super.key, required this.report});
  @override Widget build(BuildContext context) { final ads = report.ads; final marketplace = report.marketplace; final events = report.events; final currencies = <String>{...p42Map(ads['charged']).keys, ...p42Map(marketplace['gmv']).keys, ...p42Map(events['gmv']).keys}; return Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [for (final currency in currencies) Padding(padding: const EdgeInsets.only(bottom: AppSpacing.sm), child: Wrap(spacing: AppSpacing.sm, runSpacing: AppSpacing.sm, children: [for (final entry in {'ads_charged': p42Map(ads['charged'])[currency], 'ads_outstanding': p42Map(ads['outstanding'])[currency], 'ads_failed': p42Map(ads['failed'])[currency], 'ads_unbilled': p42Map(ads['unbilled'])[currency], 'marketplace_gmv': p42Map(marketplace['gmv'])[currency], 'marketplace_refunded': p42Map(marketplace['refunded'])[currency], 'events_gmv': p42Map(events['gmv'])[currency]}.entries) SizedBox(width: 190, child: HBCard(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text('admin.revenue.kpi.${entry.key}'.tr()), Text(_money(context, p42Int(entry.value), currency), style: context.textStyles.titleLarge)])))])), Wrap(spacing: AppSpacing.sm, runSpacing: AppSpacing.sm, children: [RevenueCountCard(label: 'admin.revenue.kpi.charges'.tr(), value: p42Int(ads['charges_count'])), RevenueCountCard(label: 'admin.revenue.kpi.credits_consumed'.tr(), value: p42Int(ads['credits_consumed'])), RevenueCountCard(label: 'admin.revenue.kpi.credits_granted'.tr(), value: p42Int(ads['credits_granted'])), RevenueCountCard(label: 'admin.revenue.kpi.orders'.tr(), value: p42Int(marketplace['orders'])), RevenueCountCard(label: 'admin.revenue.kpi.tickets'.tr(), value: p42Int(events['tickets'])), RevenueCountCard(label: 'admin.revenue.kpi.promo'.tr(), value: p42Int(report.promo['codes_active']))]), const SizedBox(height: AppSpacing.md), HBCard(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text('admin.revenue.commission_note'.tr()), const SizedBox(height: AppSpacing.md), if (p42Maps(ads['series']).isNotEmpty) HbBarChart(points: [for (final item in p42Maps(ads['series'])) HbBarChartPoint(day: DateTime.tryParse(item['period'].toString()) ?? DateTime.now(), value: p42Int(item['charged']))])])), const SizedBox(height: AppSpacing.md), RevenueTable(title: 'admin.revenue.top_advertisers'.tr(), rows: p42Maps(ads['top_advertisers']), country: false), const SizedBox(height: AppSpacing.md), RevenueTable(title: 'admin.revenue.by_country'.tr(), rows: p42Maps(ads['by_country']), country: true)]); }
}

class RevenueCountCard extends StatelessWidget { final String label; final int value; const RevenueCountCard({super.key, required this.label, required this.value}); @override Widget build(BuildContext context) => SizedBox(width: 170, child: HBCard(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text(label), Text('$value', style: context.textStyles.headlineSmall)]))); }
class RevenueTable extends StatelessWidget { final String title; final List<Map<String, dynamic>> rows; final bool country; const RevenueTable({super.key, required this.title, required this.rows, required this.country}); @override Widget build(BuildContext context) => HBCard(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text(title, style: context.textStyles.titleMedium), AdminDataTable(headers: [country ? 'admin.revenue.country'.tr() : 'admin.revenue.advertiser'.tr(), 'admin.revenue.account_kind'.tr(), 'admin.revenue.charges'.tr(), 'admin.revenue.charged'.tr()], emptyMessage: 'admin.revenue.empty'.tr(), rows: [for (final row in rows) [Text((country ? row['country_code'] : row['name'])?.toString() ?? ''), Text(country ? '' : 'admin.advertisers.kind.${row['kind'] ?? 'personal'}'.tr()), Text('${p42Int(row['charges'])}'), Text(_money(context, p42Int(row['charged']), row['currency_code']?.toString() ?? 'EUR'))]])])); }
String _money(BuildContext context, int amount, String currency) => MoneyFormatter.format(amountMinor: amount, currencyCode: currency, locale: context.locale);